'use strict';
// User-supplied Misa recordings; original MP3 bytes, usable offline and in local files.
const BundledCheers=(()=>{const files={"start":"","question":"","correct":"","shoot":"","goal":"","retry":"","clear":""},cache=new Map();function blob(event){if(!files[event])return null;if(!cache.has(event)){const raw=atob(files[event]),bytes=Uint8Array.from(raw,c=>c.charCodeAt(0));cache.set(event,new Blob([bytes],{type:'audio/mpeg'}));}return cache.get(event);}return{blob};})();
